import {toast} from "vy/ui";
import {SP} from "vy/v25-splits";
const IMG={"hero": "data:image/webp;base64,", "anat": "data:image/webp;base64,", "i_goal": "data:image/webp;base64,", "i_level": "data:image/webp;base64,", "i_split": "data:image/webp;base64,", "i_minutes": "data:image/webp;base64,", "i_equip": "data:image/webp;base64,", "i_days": "data:image/webp;base64,", "i_primary": "data:image/webp;base64,", "i_secondary": "data:image/webp;base64,"};
const KP="vyronV25Prog",KS="vyronV25Split";
const GOAL=[["muscle","بناء العضلات","hypertrophy"],["fat","خسارة الدهون","fatloss"],["strength","القوة","strength"],["general","اللياقة العامة","general"]];
const LVL=[["beginner","مبتدئ"],["intermediate","متوسط"],["advanced","متقدم"]];
const MIN=[["30","30 دقيقة"],["45","45 دقيقة"],["60","60 دقيقة"],["90","90 دقيقة"]];
const EQ=[["body","وزن الجسم"],["db","دمبل"],["bar","بار"],["mach","أجهزة"],["mixed","معدات متعددة"]];
const DAYS=[2,3,4,5,6].map(n=>[String(n),n+" أيام"]);
const PRI=[["strength","القوة"],["endurance","التحمل"],["flex","المرونة"]];
const SEC=[["speed","السرعة"],["balance","التوازن"],["agility","الرشاقة"]];
const CARDS=[["goal","الهدف التدريبي",GOAL,0],["level","مستوى الخبرة",LVL,0],["split","نظام التدريب",null,0],["minutes","مدة الحصة",MIN,0],["equip","المعدات المتاحة",EQ,1],["days","عدد الحصص أسبوعياً",DAYS,0],["primary","القدرة البدنية الأساسية",PRI,0],["secondary","القدرات الثانوية",SEC,1]];
const rd=k=>{try{return JSON.parse(localStorage.getItem(k))}catch{return null}};
const P0=()=>{let p=rd(KP);if(!p){p={goal:"",level:"",minutes:"",equip:[],days:"",primary:"",secondary:[]};const a=(rd("vyronV23")||{}).athlete;if(a&&a.level)p.level=a.level==="pro"?"advanced":a.level}return p};
let P=P0();
const save=()=>{try{localStorage.setItem(KP,JSON.stringify(P))}catch{toast("تعذر حفظ الإعدادات")}};
const spl=()=>{const o=rd(KS);return o&&SP.find(s=>s.id===o.id)};
const lab=(opts,v)=>(opts.find(o=>o[0]===v)||[])[1];
const val=k=>{const c=CARDS.find(x=>x[0]===k);if(k==="split"){const s=spl();return s?s.en:""}const v=P[k];return Array.isArray(v)?v.map(x=>lab(c[2],x)).join(" + "):lab(c[2],v)||""};
const missing=()=>CARDS.filter(c=>!c[3]&&!val(c[0])).map(c=>c[1]).concat(P.equip.length?[]:["المعدات المتاحة"]).filter((x,i,a)=>a.indexOf(x)===i);
const LI=["مبتدئ","متوسط","متقدم"];
function fit(){const s=spl(),L=[],ok=(t,g=true)=>L.push([g,t]);if(P.goal)ok(`برنامج موجّه نحو: ${lab(GOAL,P.goal)}`);
if(s&&P.days){const n=(s.days.match(/\d/g)||[]).map(Number),lo=Math.min(...n),hi=Math.max(...n),d=+P.days,good=n.length&&(s.id==="ppl"?[3,6].includes(d):d>=lo&&d<=hi);ok(good?`${P.days} أيام مناسبة لنظام ${s.ar}`:`نظام ${s.ar} يُنفَّذ عادةً بـ ${s.days} أيام وأنت اخترت ${P.days}`,good)}
if(s&&P.level){const m=s.lv.split(" إلى "),a=LI.indexOf(m[0]),b=LI.indexOf(m[1]||m[0]),i=["beginner","intermediate","advanced"].indexOf(P.level),g=i>=a&&i<=b;ok(g?"النظام مناسب لمستوى خبرتك":`النظام يناسب عادةً: ${s.lv}`,g)}
if(s&&P.minutes){const sh=+P.minutes<=30&&["ppl","bro","torso","upper"].includes(s.id);ok(sh?"حصة 30 دقيقة قد تحدّ من الحجم في هذا النظام":"مدة الحصة مناسبة للنظام",!sh)}
if(P.equip.length){const bw=P.equip.length===1&&P.equip[0]==="body"&&["muscle","strength"].includes(P.goal);ok(bw?"وزن الجسم وحده يحدّ من زيادة الحمل التدريجي":"المعدات المتاحة كافية للبدء",!bw)}
return L}
function prop(){const s=spl(),st=Math.max(20,Math.min(90,({muscle:60,strength:80,fat:40,general:50}[P.goal]||50)+(P.primary==="strength"?10:P.primary==="endurance"?-15:0))),f=fit(),m=missing();
return `<section class="cf-prop"><span class="cf-tag">★ البرنامج المقترح</span><div class="cf-pb"><img src="${IMG.anat}" alt="" width="320" height="262"><div>${s?`<h4>العضلات المستهدفة · ${s.ar}</h4><div class="cf-chips">${s.m.map(x=>`<i>${x}</i>`).join("")}</div>`:`<h4>اختر نظام التدريب لعرض العضلات المستهدفة</h4>`}${P.goal?`<h4>توزيع القوة والتحمل <small>(تقدير توجيهي)</small></h4><div class="cf-bar"><b style="width:${st}%">قوة ${st}%</b><span>تحمل ${100-st}%</span></div>`:""}</div></div>
<ul>${f.map(([g,t])=>`<li class="${g?"ok":"wn"}">${g?"✓":"!"} ${t}</li>`).join("")}</ul>${m.length?`<p class="cf-miss">لإكمال الإعداد: ${m.join("، ")}</p>`:""}</section>`}
function grid(){return CARDS.map(([k,t,o,mu])=>{const v=val(k);return `<button class="cf-card${v?"":" emp"}" data-cf="${k}"><img src="${IMG["i_"+k]}" alt="" width="40" height="40"><div><span>${t}${!mu&&!v?" *":""}</span><b>${v||"اختر"}</b></div><em>‹</em></button>`}).join("")}
export function configPage(){return `<div class="cf"><button class="cf-back" data-cf="back">‹ أنظمة التدريب</button><section class="cf-hero"><img src="${IMG.hero}" alt="" width="380" height="358"><div><h1>إعداد البرنامج التدريبي</h1><small>Program Configuration</small><p>خصص برنامجك التدريبي حسب أهدافك ومستواك وإمكانياتك.</p></div></section><div class="cf-grid" id="cfGrid">${grid()}</div><div id="cfProp">${prop()}</div><div class="cf-act"><button class="cf-edit" data-cf="edit">⟳ تعديل الإعدادات</button><button class="cf-go" data-cf="go">▶ متابعة إلى التمارين</button></div></div>`}
function sheet(k,refresh){const c=CARDS.find(x=>x[0]===k);if(!c[2])return;const mu=c[3],o=document.createElement("div");o.className="cf-ov";const draw=()=>{o.innerHTML=`<div class="cf-sh" role="dialog"><h3>${c[1]}</h3><div class="cf-opts">${c[2].map(([v,l])=>{const on=mu?P[k].includes(v):P[k]===v;return `<button class="${on?"on":""}" data-v="${v}">${on?"✓ ":""}${l}</button>`}).join("")}</div>${mu?'<button class="cf-done">تم</button>':""}</div>`};draw();
o.onclick=e=>{if(e.target===o||e.target.closest(".cf-done")){o.remove();return}const b=e.target.closest("[data-v]");if(!b)return;const v=b.dataset.v;if(mu){P[k]=P[k].includes(v)?P[k].filter(x=>x!==v):[...P[k],v];draw()}else{P[k]=v;o.remove()}save();refresh()};document.body.appendChild(o)}
export function bindConfig(render){const refresh=()=>{document.getElementById("cfGrid").innerHTML=grid();document.getElementById("cfProp").innerHTML=prop()};
const open=k=>k==="split"?render("v25-splits"):sheet(k,refresh);
document.querySelector(".cf").onclick=async e=>{const b=e.target.closest("[data-cf]");if(!b)return;const a=b.dataset.cf;
if(a==="back")return render("v25-splits");if(a==="edit"){const m=CARDS.find(c=>!c[3]&&!val(c[0]));return open(m?m[0]:"goal")}
if(a==="go"){const m=missing();if(m.length){toast("أكمل: "+m[0]+(m.length>1?` (+${m.length-1})`:""));return}const s=spl(),o=rd(KS)||{};o.days=String(P.days);o.goal=GOAL.find(g=>g[0]===P.goal)[2];o.cfg=P;try{localStorage.setItem(KS,JSON.stringify(o))}catch{}save();await render("v22-program");return}
open(a)}}
const CSS=`.cf{padding:0 0 110px;direction:rtl;font-family:Tajawal,system-ui,sans-serif;color:#f4f7f5;max-width:560px;margin:auto}.cf button{font:inherit;color:inherit;cursor:pointer;-webkit-tap-highlight-color:transparent}.cf-back{background:none;border:0;color:#9fb0a8!important;min-height:44px;padding:0 4px}
.cf-hero{position:relative;overflow:hidden;border-radius:18px;min-height:210px;display:flex;background:radial-gradient(120% 100% at 0 0,#0e3a22,#050807 70%)}.cf-hero img{position:absolute;left:0;bottom:0;height:100%;width:auto;max-width:46%;object-fit:cover;object-position:left;mask-image:linear-gradient(90deg,#000 65%,transparent)}.cf-hero>div{position:relative;margin-inline-end:auto;max-width:56%;padding:16px 12px;text-align:right}.cf-hero h1{margin:0;font:800 clamp(20px,6.5vw,27px) Alexandria,Tajawal,sans-serif;line-height:1.3}.cf-hero small{display:block;color:#9fb0a8;margin:4px 0 8px}.cf-hero p{margin:0;font-size:12.5px;color:#9fb0a8;line-height:1.6}
.cf-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin:12px 0}.cf-card{display:flex;align-items:center;gap:8px;padding:8px;min-height:68px;text-align:right;background:linear-gradient(#0d1411,#070a09);border:1.5px solid #1f3a2b;border-radius:14px}.cf-card img{width:40px;height:40px;object-fit:cover;border-radius:8px}.cf-card div{flex:1;min-width:0}.cf-card span{display:block;font-size:11.5px;color:#c9d6cf}.cf-card b{display:block;font-size:13px;color:#3dff7a;overflow-wrap:anywhere}.cf-card.emp b{color:#6f817a;font-weight:500}.cf-card em{font-style:normal;color:#3dff7a}
.cf-prop{border:1.5px solid #27e068;border-radius:18px;background:linear-gradient(#08110c,#050807);padding:12px;position:relative;margin-top:14px}.cf-tag{display:inline-block;background:#27e068;color:#02130a;font-weight:800;font-size:13px;padding:3px 12px;border-radius:10px}.cf-pb{display:flex;gap:10px;align-items:center;margin-top:8px}.cf-pb img{width:38%;border-radius:10px}.cf-pb>div{flex:1}.cf-pb h4{margin:6px 0;font-size:13px}.cf-pb small{color:#9fb0a8;font-weight:400}.cf-chips{display:flex;flex-wrap:wrap;gap:4px}.cf-chips i{font-style:normal;font-size:11px;padding:2px 8px;border-radius:9px;background:#12241a;border:1px solid #1f3a2b}.cf-bar{display:flex;height:26px;border-radius:13px;overflow:hidden;background:#12241a;font-size:11px;line-height:26px}.cf-bar b{background:#17c552;color:#02130a;padding:0 8px;white-space:nowrap}.cf-bar span{padding:0 8px;color:#c9d6cf;white-space:nowrap}
.cf-prop ul{list-style:none;padding:0;margin:10px 0 0}.cf-prop li{font-size:13px;margin:6px 0;line-height:1.5}.cf-prop li.ok{color:#d8f5e3}.cf-prop li.wn{color:#ffcf6b}.cf-miss{font-size:12px;color:#9fb0a8;margin:8px 0 0}.cf-act{display:flex;gap:8px;margin-top:12px}.cf-edit,.cf-go{min-height:52px;border-radius:26px;font-weight:700}.cf-edit{flex:1;background:#0a120d;border:1.5px solid #27e068}.cf-go{flex:1.4;border:0;background:linear-gradient(#4dff8a,#17c552);color:#02130a!important;font-weight:800;font-size:15px}
.cf-ov{position:fixed;inset:0;z-index:99999;background:#000b;display:flex;align-items:flex-end;direction:rtl}.cf-sh{width:100%;max-width:560px;margin:auto;padding:16px 14px calc(24px + env(safe-area-inset-bottom,0px));border-radius:20px 20px 0 0;background:#0a110d;border:1.5px solid #27e068;color:#f4f7f5;font-family:Tajawal,system-ui,sans-serif}.cf-sh h3{margin:0 0 10px}.cf-opts{display:flex;flex-wrap:wrap;gap:8px}.cf-opts button,.cf-done{min-height:46px;padding:0 16px;border-radius:23px;border:1.5px solid #1f3a2b;background:#0d1411;color:#f4f7f5;font:inherit}.cf-opts button.on{border-color:#27e068;background:#0f3a21}.cf-done{width:100%;margin-top:12px;border:0;background:linear-gradient(#4dff8a,#17c552);color:#02130a;font-weight:800}`;
if(!document.getElementById("cf-css")){const s=document.createElement("style");s.id="cf-css";s.textContent=CSS;document.head.appendChild(s)}
